function longestSubstringGrapheme(s) {
    if (s.length === 0) return 0;

    // Check for Intl.Segmenter support
    if (!Intl.Segmenter) {
        console.warn("Intl.Segmenter not supported. Falling back to code unit handling.");
        return longestSubstring(s);
    }

    const segmenter = new Intl.Segmenter(undefined, { granularity: 'grapheme' });
    const segments = segmenter.segment(s);
    const segmentArray = Array.from(segments);

    const graphemeSet = new Set();
    let maxLength = 0;
    let left = 0;

    for (let right = 0; right < segmentArray.length; right++) {
        const currentGrapheme = segmentArray[right].segment;

        while (graphemeSet.has(currentGrapheme)) {
            graphemeSet.delete(segmentArray[left].segment);
            left++;
        }

        graphemeSet.add(currentGrapheme);
        maxLength = Math.max(maxLength, right - left + 1);
    }

    return maxLength;
}
```

**Runtime Support Policy**:
- Use `Intl.Segmenter` when available (modern browsers, Node.js 16+)
- Fall back to code unit handling for older environments
- Document the limitation in the function's JSDoc

### 3. Why Same Unit Comparison Matters

When comparing brute-force and optimized implementations:

1. **Consistency**: Both must measure length in the same unit to ensure fair comparison
2. **Correctness**: Grapheme-aware implementations will give different results than code-unit-based ones
3. **Performance**: The complexity analysis must account for the actual unit of measurement

Example discrepancy:
- "café" (e + combining accent) is 4 code points but 3 graphemes
- Brute-force using code points would return 4
- Optimized using graphemes would return 3
- Comparing them directly would be invalid

